"""Exceptions used by minisql."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Parser for the SELECT dialect described in SPEC.md."""

from .errors import QueryError
from .lexer import tokenize


class Expr:
    __slots__ = ("text", "start", "end")

    def __init__(self):
        self.text = ""
        self.start = 0
        self.end = 0


class Literal(Expr):
    __slots__ = ("value",)

    def __init__(self, value):
        Expr.__init__(self)
        self.value = value


class Column(Expr):
    __slots__ = ("name", "quoted", "plain", "index")

    def __init__(self, name, quoted=False, index=None):
        Expr.__init__(self)
        self.name = name
        self.quoted = quoted
        self.plain = True
        self.index = index


class FuncCall(Expr):
    __slots__ = ("name", "args", "star")

    def __init__(self, name, args, star=False):
        Expr.__init__(self)
        self.name = name
        self.args = args
        self.star = star


class Unary(Expr):
    __slots__ = ("op", "operand")

    def __init__(self, op, operand):
        Expr.__init__(self)
        self.op = op
        self.operand = operand


class Binary(Expr):
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        Expr.__init__(self)
        self.op = op
        self.left = left
        self.right = right


class IsNull(Expr):
    __slots__ = ("operand", "negated")

    def __init__(self, operand, negated):
        Expr.__init__(self)
        self.operand = operand
        self.negated = negated


class InExpr(Expr):
    __slots__ = ("operand", "items", "negated")

    def __init__(self, operand, items, negated):
        Expr.__init__(self)
        self.operand = operand
        self.items = items
        self.negated = negated


class BetweenExpr(Expr):
    __slots__ = ("operand", "low", "high", "negated")

    def __init__(self, operand, low, high, negated):
        Expr.__init__(self)
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated


class LikeExpr(Expr):
    __slots__ = ("operand", "pattern", "negated")

    def __init__(self, operand, pattern, negated):
        Expr.__init__(self)
        self.operand = operand
        self.pattern = pattern
        self.negated = negated


class SelectItem:
    __slots__ = ("expr", "alias")

    def __init__(self, expr, alias=None):
        self.expr = expr
        self.alias = alias


class OrderItem:
    __slots__ = ("expr", "descending")

    def __init__(self, expr, descending=False):
        self.expr = expr
        self.descending = descending


class Query:
    __slots__ = (
        "distinct", "select_all", "items", "table", "where", "group_by",
        "having", "order_by", "limit", "offset",
    )

    def __init__(self):
        self.distinct = False
        self.select_all = False
        self.items = []
        self.table = ""
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []
        self.limit = None
        self.offset = None


_COMPARISONS = frozenset(("=", "!=", "<>", "<", "<=", ">", ">="))


class Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -------------------------------------------------
    def peek(self, offset=0):
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def advance(self):
        token = self.peek()
        if token.kind != "EOF":
            self.pos += 1
        return token

    def at_op(self, value):
        token = self.peek()
        return token.kind == "OP" and token.value == value

    def at_keyword(self, value):
        token = self.peek()
        return token.kind == "KEYWORD" and token.value == value

    def match_op(self, value):
        if self.at_op(value):
            return self.advance()
        return None

    def match_keyword(self, value):
        if self.at_keyword(value):
            return self.advance()
        return None

    def expect_op(self, value):
        if not self.at_op(value):
            self.syntax("expected %r" % value)
        return self.advance()

    def expect_keyword(self, value):
        if not self.at_keyword(value):
            self.syntax("expected %s" % value)
        return self.advance()

    def expect_name(self):
        token = self.peek()
        if token.kind not in ("NAME", "QNAME"):
            self.syntax("expected a name")
        return self.advance()

    def syntax(self, message):
        token = self.peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        raise QueryError("%s at position %d" % (message, token.start))

    def _span(self, expr, start, end):
        expr.start = start
        expr.end = end
        expr.text = self.sql[start:end]
        return expr

    # -- query ---------------------------------------------------------
    def parse(self):
        query = Query()
        self.expect_keyword("SELECT")
        if self.match_keyword("DISTINCT"):
            query.distinct = True

        if self.match_op("*"):
            query.select_all = True
            if self.at_op(","):
                self.syntax("'*' must be the only selected column")
        else:
            query.items.append(self.parse_select_item())
            while self.match_op(","):
                query.items.append(self.parse_select_item())

        self.expect_keyword("FROM")
        query.table = self.expect_name().value

        if self.match_keyword("WHERE"):
            query.where = self.parse_expression()

        if self.match_keyword("GROUP"):
            self.expect_keyword("BY")
            query.group_by.append(self.parse_expression())
            while self.match_op(","):
                query.group_by.append(self.parse_expression())

        if self.match_keyword("HAVING"):
            query.having = self.parse_expression()

        if self.match_keyword("ORDER"):
            self.expect_keyword("BY")
            query.order_by.append(self.parse_order_item())
            while self.match_op(","):
                query.order_by.append(self.parse_order_item())

        if self.match_keyword("LIMIT"):
            query.limit = self.parse_limit_value()
            if self.match_keyword("OFFSET"):
                query.offset = self.parse_limit_value()

        self.match_op(";")
        if self.peek().kind != "EOF":
            self.syntax("unexpected token")
        return query

    def parse_select_item(self):
        expr = self.parse_expression()
        alias = None
        if self.match_keyword("AS"):
            alias = self.expect_name().value
        elif self.peek().kind in ("NAME", "QNAME"):
            alias = self.advance().value
        return SelectItem(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expression()
        descending = False
        if self.match_keyword("DESC"):
            descending = True
        else:
            self.match_keyword("ASC")
        return OrderItem(expr, descending)

    def parse_limit_value(self):
        token = self.peek()
        if token.kind != "NUMBER" or "." in token.text:
            self.syntax("expected an integer")
        self.advance()
        return int(token.text)

    # -- expressions ---------------------------------------------------
    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        expr = self.parse_and()
        while True:
            token = self.match_keyword("OR")
            if token is None:
                return expr
            right = self.parse_and()
            expr = self._span(Binary("OR", expr, right), expr.start, right.end)

    def parse_and(self):
        expr = self.parse_not()
        while True:
            token = self.match_keyword("AND")
            if token is None:
                return expr
            right = self.parse_not()
            expr = self._span(Binary("AND", expr, right), expr.start, right.end)

    def parse_not(self):
        token = self.match_keyword("NOT")
        if token is not None:
            operand = self.parse_not()
            return self._span(Unary("NOT", operand), token.start, operand.end)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()

        token = self.peek()
        if token.kind == "OP" and token.value in _COMPARISONS:
            self.advance()
            right = self.parse_additive()
            return self._span(
                Binary(token.value, left, right), left.start, right.end
            )

        if self.match_keyword("IS"):
            negated = self.match_keyword("NOT") is not None
            null_token = self.expect_keyword("NULL")
            return self._span(
                IsNull(left, negated), left.start, null_token.end
            )

        negated = False
        keyword = None
        not_token = self.match_keyword("NOT")
        if not_token is not None:
            token = self.peek()
            if token.kind == "KEYWORD" and token.value in (
                "IN", "BETWEEN", "LIKE"
            ):
                keyword = self.advance().value
                negated = True
            else:
                self.syntax("expected IN, BETWEEN, or LIKE after NOT")
        else:
            token = self.peek()
            if token.kind == "KEYWORD" and token.value in (
                "IN", "BETWEEN", "LIKE"
            ):
                keyword = self.advance().value

        if keyword == "IN":
            self.expect_op("(")
            items = [self.parse_expression()]
            while self.match_op(","):
                items.append(self.parse_expression())
            close = self.expect_op(")")
            return self._span(
                InExpr(left, items, negated), left.start, close.end
            )

        if keyword == "BETWEEN":
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return self._span(
                BetweenExpr(left, low, high, negated), left.start, high.end
            )

        if keyword == "LIKE":
            pattern = self.parse_additive()
            return self._span(
                LikeExpr(left, pattern, negated), left.start, pattern.end
            )

        return left

    def parse_additive(self):
        expr = self.parse_multiplicative()
        while True:
            token = self.peek()
            if token.kind != "OP" or token.value not in ("+", "-", "||"):
                return expr
            self.advance()
            right = self.parse_multiplicative()
            expr = self._span(
                Binary(token.value, expr, right), expr.start, right.end
            )

    def parse_multiplicative(self):
        expr = self.parse_unary()
        while True:
            token = self.peek()
            if token.kind != "OP" or token.value not in ("*", "/"):
                return expr
            self.advance()
            right = self.parse_unary()
            expr = self._span(
                Binary(token.value, expr, right), expr.start, right.end
            )

    def parse_unary(self):
        token = self.match_op("-")
        if token is not None:
            operand = self.parse_unary()
            return self._span(Unary("-", operand), token.start, operand.end)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()

        if token.kind == "NUMBER":
            self.advance()
            text = token.text
            value = float(text) if "." in text else int(text)
            return self._span(Literal(value), token.start, token.end)

        if token.kind == "STRING":
            self.advance()
            return self._span(Literal(token.value), token.start, token.end)

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.advance()
                return self._span(Literal(None), token.start, token.end)
            if token.value == "TRUE":
                self.advance()
                return self._span(Literal(True), token.start, token.end)
            if token.value == "FALSE":
                self.advance()
                return self._span(Literal(False), token.start, token.end)
            self.syntax("expected an expression")

        if token.kind == "NAME":
            self.advance()
            if self.match_op("("):
                return self.parse_call(token)
            column = Column(token.value)
            return self._span(column, token.start, token.end)

        if token.kind == "QNAME":
            self.advance()
            column = Column(token.value, quoted=True)
            return self._span(column, token.start, token.end)

        if token.kind == "OP" and token.value == "(":
            open_token = self.advance()
            inner = self.parse_expression()
            close_token = self.expect_op(")")
            self._span(inner, open_token.start, close_token.end)
            if isinstance(inner, Column):
                inner.plain = False
            return inner

        self.syntax("expected an expression")

    def parse_call(self, name_token):
        args = []
        star = False
        if self.match_op("*"):
            star = True
            close_token = self.expect_op(")")
        elif self.at_op(")"):
            close_token = self.advance()
        else:
            args.append(self.parse_expression())
            while self.match_op(","):
                args.append(self.parse_expression())
            close_token = self.expect_op(")")
        call = FuncCall(name_token.value, args, star)
        return self._span(call, name_token.start, close_token.end)


def parse(sql):
    """Parse ``sql`` and return a :class:`Query`."""
    return Parser(sql).parse()

"""Value helpers: NULL logic, comparisons, and scalar functions."""

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

from .errors import QueryError


def is_number(value):
    """True for integers and floats, but not booleans."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def is_bool(value):
    return isinstance(value, bool)


def type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def check_bool(value, operator):
    if value is None or isinstance(value, bool):
        return
    raise QueryError(
        "%s requires boolean operands, got %s" % (operator, type_name(value))
    )


def logic_not(value):
    check_bool(value, "NOT")
    if value is None:
        return None
    return not value


def logic_and(left, right):
    check_bool(left, "AND")
    check_bool(right, "AND")
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def logic_or(left, right):
    check_bool(left, "OR")
    check_bool(right, "OR")
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def compare_values(left, right):
    """Order two non-NULL values, raising QueryError for unlike types."""
    if left is None and right is None:
        return 0
    if left is None:
        return -1
    if right is None:
        return 1
    if is_number(left) and is_number(right):
        return (left > right) - (left < right)
    if isinstance(left, str) and isinstance(right, str):
        return (left > right) - (left < right)
    if isinstance(left, bool) and isinstance(right, bool):
        return (left > right) - (left < right)
    raise QueryError(
        "cannot compare %s with %s" % (type_name(left), type_name(right))
    )


def compare_op(left, right, operator):
    if left is None or right is None:
        return None
    order = compare_values(left, right)
    if operator == "=":
        return order == 0
    if operator in ("!=", "<>"):
        return order != 0
    if operator == "<":
        return order < 0
    if operator == "<=":
        return order <= 0
    if operator == ">":
        return order > 0
    if operator == ">=":
        return order >= 0
    raise QueryError("unknown comparison operator %r" % operator)


def apply_in(value, items, negated):
    if value is None:
        return None
    saw_null = False
    for item in items:
        if item is None:
            saw_null = True
            continue
        if compare_op(value, item, "="):
            return not negated
    if saw_null:
        return None
    return negated


def apply_between(value, low, high, negated):
    result = logic_and(compare_op(low, value, "<="),
                       compare_op(value, high, "<="))
    return logic_not(result) if negated else result


def _like_regex(pattern):
    pieces = []
    for char in pattern:
        if char == "%":
            pieces.append(".*")
        elif char == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(char))
    return "".join(pieces)


def apply_like(value, pattern, negated):
    if value is None or pattern is None:
        return None
    if not isinstance(value, str):
        raise QueryError("LIKE requires a string, got %s" % type_name(value))
    if not isinstance(pattern, str):
        raise QueryError("LIKE pattern must be a string, got %s"
                         % type_name(pattern))
    matched = re.fullmatch(_like_regex(pattern), value, re.DOTALL) is not None
    return not matched if negated else matched


def text_value(value):
    return value if isinstance(value, str) else str(value)


def normalize_key(value):
    """A hashable key making NULLs equal and keeping bools apart from ints."""
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("boolean", value)
    if isinstance(value, (int, float)):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("other", type(value).__name__, value)


def _round(value, places=None):
    if places is None:
        if isinstance(value, int):
            return value
        try:
            decimal_value = Decimal(str(value))
        except InvalidOperation:
            raise QueryError("ROUND cannot handle %r" % (value,))
        try:
            with localcontext() as context:
                context.prec = max(28, len(decimal_value.as_tuple().digits) + 2)
                rounded = decimal_value.quantize(Decimal(1),
                                                 rounding=ROUND_HALF_UP)
        except InvalidOperation:
            raise QueryError("ROUND cannot handle %r" % (value,))
        return int(rounded)

    if not isinstance(places, int) or isinstance(places, bool):
        raise QueryError("ROUND's second argument must be an integer")
    try:
        decimal_value = Decimal(value) if isinstance(value, int) else Decimal(
            str(value)
        )
    except InvalidOperation:
        raise QueryError("ROUND cannot handle %r" % (value,))
    quantum = Decimal(1).scaleb(-places)
    digits = len(decimal_value.as_tuple().digits)
    try:
        with localcontext() as context:
            context.prec = max(28, digits + abs(places) + 2)
            rounded = decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise QueryError("ROUND cannot handle %r with %r places"
                         % (value, places))
    return float(rounded)


def call_scalar(name, args):
    """Evaluate a scalar function on already-evaluated arguments."""
    upper = name.upper()

    if upper == "COALESCE":
        for value in args:
            if value is not None:
                return value
        return None

    if any(value is None for value in args):
        return None

    if upper in ("LOWER", "UPPER", "LENGTH"):
        value = args[0]
        if not isinstance(value, str):
            raise QueryError("%s requires a string, got %s"
                             % (upper, type_name(value)))
        if upper == "LOWER":
            return value.lower()
        if upper == "UPPER":
            return value.upper()
        return len(value)

    if upper == "ABS":
        value = args[0]
        if not is_number(value):
            raise QueryError("ABS requires a number, got %s" % type_name(value))
        return abs(value)

    if upper == "ROUND":
        value = args[0]
        if not is_number(value):
            raise QueryError("ROUND requires a number, got %s"
                             % type_name(value))
        if len(args) == 1:
            return _round(value)
        return _round(value, args[1])

    raise QueryError("unknown function: %s" % name)

"""Query planning and execution for minisql."""

import csv
import os
import re
from functools import cmp_to_key

from .errors import QueryError
from .parser import (
    BetweenExpr, Binary, Column, FuncCall, InExpr, IsNull, LikeExpr,
    Literal, Unary, parse,
)
from .values import (
    apply_between, apply_in, apply_like, call_scalar, compare_op,
    compare_values, is_number, logic_and, logic_not, logic_or,
    normalize_key, text_value, type_name,
)

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")

AGGREGATES = frozenset(("COUNT", "SUM", "AVG", "MIN", "MAX"))
SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


class Result:
    """The result of running a query."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):  # pragma: no cover - convenience only
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


class Table:
    __slots__ = ("name", "columns", "rows")

    def __init__(self, name, columns, rows):
        self.name = name
        self.columns = columns
        self.rows = rows


class _Binder:
    __slots__ = ("columns", "lookup")

    def __init__(self, table):
        self.columns = table.columns
        lookup = {}
        for index, name in enumerate(table.columns):
            lookup.setdefault(name.casefold(), index)
        self.lookup = lookup

    def index_of(self, name):
        try:
            return self.lookup[name.casefold()]
        except KeyError:
            raise QueryError("unknown column: %s" % name)

    def name_of(self, index):
        return self.columns[index]


# -- table loading -----------------------------------------------------

def _convert_field(text):
    if text == "":
        return None
    if _INT_RE.match(text):
        return int(text)
    if _DECIMAL_RE.match(text):
        return float(text)
    return text


def load_table(directory, name):
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        handle = open(path, "r", newline="", encoding="utf-8-sig")
    except FileNotFoundError:
        raise QueryError("table not found: %s" % name)
    except OSError as exc:
        raise QueryError("cannot open table %s: %s" % (name, exc))

    try:
        with handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %s has no header" % name)
            except csv.Error as exc:
                raise QueryError("cannot read table %s: %s" % (name, exc))

            if not header:
                raise QueryError("table %s has no columns" % name)

            rows = []
            for fields in reader:
                if len(fields) != len(header):
                    raise QueryError(
                        "table %s has a row with %d fields, expected %d"
                        % (name, len(fields), len(header))
                    )
                rows.append([_convert_field(field) for field in fields])
    except UnicodeDecodeError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))
    except csv.Error as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))

    return Table(name, header, rows)


# -- expression structure ---------------------------------------------

def _children(expr):
    if isinstance(expr, Unary):
        return (expr.operand,)
    if isinstance(expr, Binary):
        return (expr.left, expr.right)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, InExpr):
        return (expr.operand,) + tuple(expr.items)
    if isinstance(expr, BetweenExpr):
        return (expr.operand, expr.low, expr.high)
    if isinstance(expr, LikeExpr):
        return (expr.operand, expr.pattern)
    if isinstance(expr, FuncCall):
        return tuple(expr.args)
    return ()


def expr_equal(left, right):
    """Structural equality, ignoring whitespace and name case."""
    if type(left) is not type(right):
        return False
    if isinstance(left, Literal):
        return normalize_key(left.value) == normalize_key(right.value)
    if isinstance(left, Column):
        return left.name.casefold() == right.name.casefold()
    if isinstance(left, FuncCall):
        return (
            left.name.upper() == right.name.upper()
            and left.star == right.star
            and len(left.args) == len(right.args)
            and all(expr_equal(a, b) for a, b in zip(left.args, right.args))
        )
    if isinstance(left, Unary):
        return left.op == right.op and expr_equal(left.operand, right.operand)
    if isinstance(left, Binary):
        return (
            left.op == right.op
            and expr_equal(left.left, right.left)
            and expr_equal(left.right, right.right)
        )
    if isinstance(left, IsNull):
        return (
            left.negated == right.negated
            and expr_equal(left.operand, right.operand)
        )
    if isinstance(left, InExpr):
        return (
            left.negated == right.negated
            and expr_equal(left.operand, right.operand)
            and len(left.items) == len(right.items)
            and all(expr_equal(a, b) for a, b in zip(left.items, right.items))
        )
    if isinstance(left, BetweenExpr):
        return (
            left.negated == right.negated
            and expr_equal(left.operand, right.operand)
            and expr_equal(left.low, right.low)
            and expr_equal(left.high, right.high)
        )
    if isinstance(left, LikeExpr):
        return (
            left.negated == right.negated
            and expr_equal(left.operand, right.operand)
            and expr_equal(left.pattern, right.pattern)
        )
    return False


def has_aggregate(expr):
    if expr is None:
        return False
    if isinstance(expr, FuncCall) and expr.name.upper() in AGGREGATES:
        return True
    return any(has_aggregate(child) for child in _children(expr))


# -- validation --------------------------------------------------------

def validate_expr(expr, binder, allow_aggregates=True, context="SELECT",
                  inside_aggregate=False):
    if isinstance(expr, Column):
        if expr.index is None:
            binder.index_of(expr.name)
        return

    if isinstance(expr, FuncCall):
        upper = expr.name.upper()
        if upper in AGGREGATES:
            if upper == "COUNT":
                if not expr.star and len(expr.args) != 1:
                    raise QueryError("COUNT expects one argument")
            else:
                if expr.star:
                    raise QueryError("%s does not accept '*'" % upper)
                if len(expr.args) != 1:
                    raise QueryError("%s expects one argument" % upper)
            if not allow_aggregates:
                if inside_aggregate:
                    raise QueryError("aggregate functions cannot be nested")
                raise QueryError(
                    "aggregate functions are not allowed in %s" % context
                )
            for arg in expr.args:
                validate_expr(arg, binder, False, "an aggregate function", True)
            return

        if upper not in SCALAR_ARITY:
            raise QueryError("unknown function: %s" % expr.name)
        minimum, maximum = SCALAR_ARITY[upper]
        if expr.star:
            raise QueryError("%s does not accept '*'" % upper)
        count = len(expr.args)
        if count < minimum or (maximum is not None and count > maximum):
            raise QueryError("%s has the wrong number of arguments" % upper)
        for arg in expr.args:
            validate_expr(arg, binder, allow_aggregates, context,
                          inside_aggregate)
        return

    for child in _children(expr):
        validate_expr(child, binder, allow_aggregates, context,
                      inside_aggregate)


def validate_grouped(expr, group_by):
    """Check that every column outside an aggregate is grouped."""
    if isinstance(expr, FuncCall) and expr.name.upper() in AGGREGATES:
        return
    if any(expr_equal(expr, group_expr) for group_expr in group_by):
        return
    if isinstance(expr, Column):
        raise QueryError(
            "column '%s' must appear in GROUP BY" % expr.name
        )
    for child in _children(expr):
        validate_grouped(child, group_by)


# -- runtime contexts --------------------------------------------------

class _RowContext:
    __slots__ = ("binder", "row")

    def __init__(self, binder, row):
        self.binder = binder
        self.row = row

    def column(self, expr):
        index = expr.index
        if index is None:
            index = self.binder.index_of(expr.name)
        return self.row[index]

    def aggregate(self, expr):
        raise QueryError("aggregate functions are not allowed here")


class _Group:
    __slots__ = ("rows", "exprs", "values", "representative")

    def __init__(self, rows, exprs, values, representative):
        self.rows = rows
        self.exprs = exprs
        self.values = values
        self.representative = representative


class _GroupContext:
    __slots__ = ("binder", "group")

    def __init__(self, binder, group):
        self.binder = binder
        self.group = group

    def match(self, expr):
        for index, group_expr in enumerate(self.group.exprs):
            if expr_equal(expr, group_expr):
                return index
        return None

    def column(self, expr):
        raise QueryError("column '%s' must appear in GROUP BY" % expr.name)

    def aggregate(self, expr):
        return _evaluate_aggregate(expr, self.group, self.binder)


# -- expression evaluation --------------------------------------------

def eval_expr(expr, context):
    if isinstance(context, _GroupContext):
        index = context.match(expr)
        if index is not None:
            return context.group.values[index]

    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        return context.column(expr)

    if isinstance(expr, Unary):
        value = eval_expr(expr.operand, context)
        return _apply_unary(expr.op, value)

    if isinstance(expr, Binary):
        left = eval_expr(expr.left, context)
        right = eval_expr(expr.right, context)
        return _apply_binary(expr.op, left, right)

    if isinstance(expr, IsNull):
        value = eval_expr(expr.operand, context)
        return (value is None) != expr.negated

    if isinstance(expr, InExpr):
        value = eval_expr(expr.operand, context)
        items = [eval_expr(item, context) for item in expr.items]
        return apply_in(value, items, expr.negated)

    if isinstance(expr, BetweenExpr):
        value = eval_expr(expr.operand, context)
        low = eval_expr(expr.low, context)
        high = eval_expr(expr.high, context)
        return apply_between(value, low, high, expr.negated)

    if isinstance(expr, LikeExpr):
        value = eval_expr(expr.operand, context)
        pattern = eval_expr(expr.pattern, context)
        return apply_like(value, pattern, expr.negated)

    if isinstance(expr, FuncCall):
        upper = expr.name.upper()
        if upper in AGGREGATES:
            return context.aggregate(expr)
        args = [eval_expr(arg, context) for arg in expr.args]
        return call_scalar(expr.name, args)

    raise QueryError("unsupported expression")


def _apply_unary(operator, value):
    if operator == "NOT":
        return logic_not(value)
    if operator == "-":
        if value is None:
            return None
        if not is_number(value):
            raise QueryError(
                "unary - requires a number, got %s" % type_name(value)
            )
        return -value
    raise QueryError("unknown unary operator %r" % operator)


def _apply_binary(operator, left, right):
    if operator == "AND":
        return logic_and(left, right)
    if operator == "OR":
        return logic_or(left, right)

    if operator in ("+", "-", "*", "/"):
        if left is None or right is None:
            return None
        if not is_number(left) or not is_number(right):
            raise QueryError(
                "cannot apply %s to %s and %s"
                % (operator, type_name(left), type_name(right))
            )
        try:
            if operator == "+":
                if isinstance(left, int) and isinstance(right, int):
                    return left + right
                return float(left) + float(right)
            if operator == "-":
                if isinstance(left, int) and isinstance(right, int):
                    return left - right
                return float(left) - float(right)
            if operator == "*":
                if isinstance(left, int) and isinstance(right, int):
                    return left * right
                return float(left) * float(right)
            if right == 0:
                return None
            return float(left) / float(right)
        except (OverflowError, ZeroDivisionError):
            raise QueryError("arithmetic error")

    if operator == "||":
        if left is None or right is None:
            return None
        return text_value(left) + text_value(right)

    return compare_op(left, right, operator)


def _evaluate_aggregate(call, group, binder):
    name = call.name.upper()

    if name == "COUNT" and call.star:
        return len(group.rows)

    argument = call.args[0] if call.args else None

    if name == "COUNT":
        count = 0
        for row in group.rows:
            value = eval_expr(argument, _RowContext(binder, row))
            if value is not None:
                count += 1
        return count

    values = []
    for row in group.rows:
        value = eval_expr(argument, _RowContext(binder, row))
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name in ("SUM", "AVG"):
        for value in values:
            if not is_number(value):
                raise QueryError(
                    "%s requires numeric values, got %s"
                    % (name, type_name(value))
                )
        try:
            total = sum(values)
            if name == "AVG":
                return float(total) / len(values)
            if any(isinstance(value, float) for value in values):
                return float(total)
            return total
        except (OverflowError, ZeroDivisionError):
            raise QueryError("arithmetic error")

    if name in ("MIN", "MAX"):
        best = values[0]
        for value in values[1:]:
            order = compare_values(value, best)
            if (name == "MIN" and order < 0) or (
                name == "MAX" and order > 0
            ):
                best = value
        return best

    raise QueryError("unknown aggregate function: %s" % call.name)


# -- planning ----------------------------------------------------------

def _expand_select(query, table):
    if not query.select_all:
        return query.items
    items = []
    for index, name in enumerate(table.columns):
        column = Column(name, quoted=True, index=index)
        column.text = name
        column.plain = True
        items.append(_SelectItem(column, None))
    return items


class _SelectItem:
    __slots__ = ("expr", "alias")

    def __init__(self, expr, alias):
        self.expr = expr
        self.alias = alias


class _OrderSpec:
    __slots__ = ("expr", "descending", "position", "output_index")

    def __init__(self, expr, descending, position=None, output_index=None):
        self.expr = expr
        self.descending = descending
        self.position = position
        self.output_index = output_index


def _output_names(items, binder):
    names = []
    for item in items:
        if item.alias is not None:
            names.append(item.alias)
        elif isinstance(item.expr, Column) and item.expr.plain:
            index = item.expr.index
            if index is None:
                index = binder.index_of(item.expr.name)
            names.append(binder.name_of(index))
        else:
            names.append(item.expr.text)
    return names


def _resolve_order(query, output_names):
    lookup = {}
    for index, name in enumerate(output_names):
        lookup.setdefault(name.casefold(), index)

    specs = []
    for item in query.order_by:
        expr = item.expr
        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            position = expr.value
            if position < 1 or position > len(output_names):
                raise QueryError(
                    "ORDER BY position %d is out of range" % position
                )
            specs.append(_OrderSpec(None, item.descending,
                                    position=position - 1))
        elif isinstance(expr, Column) and expr.name.casefold() in lookup:
            specs.append(_OrderSpec(
                None, item.descending,
                output_index=lookup[expr.name.casefold()],
            ))
        else:
            specs.append(_OrderSpec(expr, item.descending))
    return specs


# -- execution ---------------------------------------------------------

def execute(sql, directory="."):
    query = parse(sql)
    table = load_table(directory, query.table)
    binder = _Binder(table)
    items = _expand_select(query, table)

    for item in items:
        validate_expr(item.expr, binder, True, "SELECT")
    if query.where is not None:
        validate_expr(query.where, binder, False, "WHERE")
    for group_expr in query.group_by:
        validate_expr(group_expr, binder, False, "GROUP BY")
    if query.having is not None:
        validate_expr(query.having, binder, True, "HAVING")
    for order_item in query.order_by:
        validate_expr(order_item.expr, binder, True, "ORDER BY")

    output_names = _output_names(items, binder)
    order_specs = _resolve_order(query, output_names)

    grouped = (
        bool(query.group_by)
        or any(has_aggregate(item.expr) for item in items)
        or has_aggregate(query.having)
        or any(has_aggregate(item.expr) for item in query.order_by)
    )

    if grouped:
        for item in items:
            validate_grouped(item.expr, query.group_by)
        if query.having is not None:
            validate_grouped(query.having, query.group_by)
        for spec in order_specs:
            if spec.expr is not None:
                validate_grouped(spec.expr, query.group_by)

    filtered = []
    for row in table.rows:
        if query.where is None:
            filtered.append(row)
        else:
            if eval_expr(query.where, _RowContext(binder, row)) is True:
                filtered.append(row)

    if grouped:
        entries = _grouped_entries(query, binder, filtered, items)
    else:
        if query.having is not None:
            kept = []
            for row in filtered:
                if eval_expr(query.having, _RowContext(binder, row)) is True:
                    kept.append(row)
            filtered = kept
        entries = []
        for row in filtered:
            context = _RowContext(binder, row)
            values = tuple(eval_expr(item.expr, context) for item in items)
            entries.append((values, context))

    return _finish(entries, output_names, query, order_specs)


def _grouped_entries(query, binder, filtered, items):
    groups = []
    if query.group_by:
        seen = {}
        for row in filtered:
            context = _RowContext(binder, row)
            values = [eval_expr(expr, context) for expr in query.group_by]
            key = tuple(normalize_key(value) for value in values)
            group = seen.get(key)
            if group is None:
                group = _Group([], list(query.group_by), values, row)
                seen[key] = group
                groups.append(group)
            group.rows.append(row)
    else:
        representative = filtered[0] if filtered else None
        groups.append(_Group(list(filtered), [], [], representative))

    kept = []
    for group in groups:
        if query.having is not None:
            context = _GroupContext(binder, group)
            if eval_expr(query.having, context) is not True:
                continue
        kept.append(group)

    entries = []
    for group in kept:
        context = _GroupContext(binder, group)
        values = tuple(eval_expr(item.expr, context) for item in items)
        entries.append((values, context))
    return entries


def _order_value(spec, values, context):
    if spec.position is not None:
        return values[spec.position]
    if spec.output_index is not None:
        return values[spec.output_index]
    return eval_expr(spec.expr, context)


def _finish(entries, output_names, query, order_specs):
    if query.distinct:
        seen = set()
        unique = []
        for values, context in entries:
            key = tuple(normalize_key(value) for value in values)
            if key not in seen:
                seen.add(key)
                unique.append((values, context))
        entries = unique

    if order_specs:
        decorated = []
        for values, context in entries:
            keys = tuple(
                _order_value(spec, values, context) for spec in order_specs
            )
            decorated.append((keys, values, context))

        def compare(left, right):
            for spec, left_key, right_key in zip(
                order_specs, left[0], right[0]
            ):
                order = compare_values(left_key, right_key)
                if spec.descending:
                    order = -order
                if order:
                    return order
            return 0

        decorated.sort(key=cmp_to_key(compare))
        entries = [(values, context) for keys, values, context in decorated]

    offset = query.offset or 0
    if query.limit is not None:
        entries = entries[offset:offset + query.limit]
    elif offset:
        entries = entries[offset:]

    return Result(output_names, [values for values, context in entries])

